WITH valid AS (SELECT *, HOUR(txn_time) AS txn_time_hour, CONCAT_WS('-', txn_type, merchant) AS txn_type_merchant_key, COALESCE(merchant, 'DIRECT') AS merchant_filled FROM transactions WHERE amount <= 3700), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM valid), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_burst_tier, SUM(CASE WHEN txn_type = 'REFUND' THEN amount ELSE 0 END) AS refund_amount, ROUND(AVG(txn_time_hour), 2) AS avg_txn_time_hour FROM sessionized GROUP BY CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING avg_txn_time_hour >= 0
